mapper.select:
SELECT DISTINCT d.id, d.department_id, d.doctor_position_id, d.degree_id, d.name, d.avatar, d.address, d.scope, d.tags, d.description, d.status, d.create_time, d.update_time, d.is_deleted FROM doctor d WHERE d.id IN
#{item}
AND EXISTS ( SELECT 1 FROM registration_schedule rs WHERE rs.doctor_id = d.id AND rs.start_time >= CURDATE() AND rs.start_time <= DATE_ADD(CURDATE(), INTERVAL #{maxAdvanceDays} DAY) AND (rs.status IS NULL OR rs.status = #{status}) ) ORDER BY d.id ASC
